async def model_response(client: httpx.AsyncClient, messages: list[dict[str, str]], max_tokens: int, selection: tuple[str, str | None, str] | None = None) -> str:
    url, key, model = selection or selected_model()
    response = await client.post(
        url,
        headers={"Authorization": f"Bearer {key}"} if key else {},
        json={"model": model, "messages": messages, "temperature": 0.1, "max_tokens": max_tokens},
        timeout=120,
    )
    response.raise_for_status()
    choice = response.json()["choices"][0]
    if choice.get("finish_reason") == "length":
        raise ValueError("Model output truncated")
    return str(choice["message"]["content"] or "").strip()


