def validate_research_request(payload: ResearchQueryRequest) -> tuple[str, str | None, str]:
    if payload.mode == "deep":
        raise HTTPException(status_code=501, detail="Mode deep belum tersedia.")
    if bool(payload.provider) != bool(payload.model):
