import { cookies } from "next/headers";
import { redirect } from "next/navigation";
import { DashboardView } from "@/components/dashboard/DashboardView";
import { DashboardResponse, ProfileData } from "@/types/dashboard";

import { LandingScene } from "@/components/landing/LandingScene";

export default async function HomePage() {
  const cookieStore = await cookies();
  const token = cookieStore.get("token")?.value;

  if (!token) {
    return <LandingScene />;
  }

  const backendUrl = process.env.BACKEND_URL || "http://127.0.0.1:8000";

  let profile: ProfileData | null = null;
  let dashboard: DashboardResponse | null = null;

  try {
    const [profileRes, dashboardRes] = await Promise.all([
      fetch(`${backendUrl}/api/profile`, {
        headers: {
          Authorization: `Bearer ${token}`,
        },
        cache: "no-store",
      }),
      fetch(`${backendUrl}/api/dashboard`, {
        headers: {
          Authorization: `Bearer ${token}`,
        },
        cache: "no-store",
      }),
    ]);

    if (!profileRes.ok || !dashboardRes.ok) {
      redirect("/login");
    }

    profile = await profileRes.json();
    dashboard = await dashboardRes.json();
  } catch {
    redirect("/login");
  }

  if (profile?.must_set_birth_date) {
    redirect("/login");
  }

  if (!dashboard || !profile) {
    redirect("/login");
  }

  return <DashboardView initialDashboard={dashboard} profile={profile} />;
}
