class NoSampleFits(ValueError):
    def __init__(self, downloaded_bytes):
        super().__init__('Budget cannot fit the Parquet metadata and one row group')
        self.downloaded_bytes = downloaded_bytes


def load_config(path):
    config = json.loads(Path(path).read_text(encoding='utf-8'))
    budget = config['max_bytes_per_domain']
    if type(budget) is not int or budget <= 0:
        raise ValueError('max_bytes_per_domain must be a positive integer')
    for domain, sources in config['domains'].items():
        if not domain.isidentifier() or not sources:
            raise ValueError(f'Invalid or empty domain: {domain}')
        names = set()
        for source in sources:
            weight = source['weight']
            if not isinstance(weight, (int, float)) or not math.isfinite(weight) or weight <= 0:
                raise ValueError(f'Invalid source weight in {domain}')
            if not source['name'].isidentifier() or source['name'] in names:
                raise ValueError(f'Invalid or duplicate source name in {domain}')
            names.add(source['name'])
            if len(source['revision']) != 40 or any(c not in '0123456789abcdef' for c in source['revision']):
                raise ValueError('Dataset revisions must be pinned commit hashes')
    return config


def list_shards(source):
    repo = source['repo']
    revision = source['revision']
    prefix = source['prefix'].strip('/')
    url = f'https://huggingface.co/api/datasets/{repo}/tree/{revision}'
    if prefix:
        url += '/' + quote(prefix, safe='/')
    url += '?limit=1000'
