#[derive(Debug, Clone)]
pub struct S3Config {
    pub endpoint: String,
    pub region: String,
    pub bucket: String,
    pub access_key: String,
    pub secret_key: String,
    pub force_path_style: bool,
    pub public_url: String,
}

impl S3Config {
    /// Builds the full streaming URL for an asset key.
    /// Example: "movies/nama-film.mp4" -> "https://s3.mesosfer.cloud/cineflix/movies/nama-film.mp4"
    pub fn get_public_url(&self, key: &str) -> String {
        let base = self.public_url.trim_end_matches('/');
        let clean_key = key.trim_start_matches('/');

        if base.ends_with(&format!("/{}", self.bucket)) {
            format!("{base}/{clean_key}")
        } else if self.force_path_style {
            format!("{base}/{}/{clean_key}", self.bucket)
        } else {
            format!("{base}/{clean_key}")
        }
    }

    /// Inverse of `get_public_url`: returns the object key for a URL under this bucket.
    pub fn key_from_public_url(&self, url: &str) -> Option<String> {
        let base = self.get_public_url("");
        let key = url.split('?').next()?.strip_prefix(&base)?;
        (!key.is_empty()).then(|| key.to_string())
    }
}

