import { Text, View } from "react-native";
import type { VideoSurfaceProps } from "./video-surface";
import { isApiPlaylist } from "./model";

export function VideoSurface({ source, onProgress }: VideoSurfaceProps) {
  const video = useRef<HTMLVideoElement>(null);
  const lastSaved = useRef(0);
  const [error, setError] = useState("");

  useEffect(() => {
    const element = video.current;
    if (!element) return;
    let active = true;
    let destroy: (() => void) | undefined;
    async function load() {
      if (!source.uri.includes(".m3u8")) {
        element!.src = source.uri;
        return;
      }
      const { default: Hls } = await import("hls.js");
      if (!active) return;
      if (!Hls.isSupported()) {
        setError(
          "Browser ini belum mendukung pemutaran HLS. Gunakan browser terbaru atau aplikasi Cineflix.",
        );
        return;
      }
      const hls = new Hls({
        xhrSetup: (xhr, url) => {
          // Playlist authentication must never be forwarded to presigned CDN segment URLs.
          if (isApiPlaylist(url, source.apiOrigin))
            xhr.setRequestHeader("Authorization", `Bearer ${source.token}`);
        },
      });
      destroy = () => hls.destroy();
      hls.on(Hls.Events.ERROR, (_, data) => {
        if (data.fatal && active)
          setError(
            "Video belum dapat diputar. Periksa koneksi atau coba lagi.",
          );
      });
      hls.attachMedia(element!);
      hls.loadSource(source.uri);
    }
    void load().catch(() => {
      if (active) setError("Pemutar video belum dapat dimuat.");
    });
    return () => {
      active = false;
      destroy?.();
    };
  }, [source]);

  return (
    <View>
      <video
        ref={video}
        controls
        autoPlay
        playsInline
        aria-label="Pemutar Cineflix"
        style={{ width: "100%", aspectRatio: "16 / 9", background: "#000" }}
        onError={() => setError("Video belum dapat diputar. Coba lagi.")}
        onTimeUpdate={(event) => {
          const element = event.currentTarget;
          if (Math.abs(element.currentTime - lastSaved.current) >= 10) {
            lastSaved.current = element.currentTime;
            onProgress(element.currentTime, element.duration);
          }
        }}
        onPause={(event) =>
          onProgress(
            event.currentTarget.currentTime,
            event.currentTarget.duration,
          )
        }
      />
      {!!error && (
        <Text
          accessibilityRole="alert"
          style={{ color: "#FF989B", padding: 16 }}
        >
          {error}
        </Text>
      )}
    </View>
  );
}
