[Service]
Type=simple
WorkingDirectory=/opt/inferance
ExecStart=/usr/local/bin/llama-swap -config /opt/inferance/deploy/llama-swap.yaml -listen 127.0.0.1:8080
Restart=on-failure
RestartSec=3
# Stop children too, including when a model fails to shut down.
KillMode=control-group
TimeoutStopSec=30
Environment=OMP_NUM_THREADS=4
Environment=OPENBLAS_NUM_THREADS=4

[Install]
