# yaml-language-server: $schema=https://raw.githubusercontent.com/mostlygeek/llama-swap/v270/config-schema.json
healthCheckTimeout: 300
globalConcurrencyLimit: 1
maxRequestBodyMB: 1

models:
  joko:
    cmd: >-
      /usr/local/bin/llama-server
      --model /opt/inferance/ai-service/models/joko/joko-q4_k_m.gguf
      --alias joko
      --host 127.0.0.1 --port ${PORT}
      --ctx-size 4096 --predict 2654 --threads 4 --threads-batch 4
      --batch-size 256 --ubatch-size 128 --parallel 1 --n-gpu-layers 0
      --chat-template-kwargs '{"enable_thinking":false}'
    ttl: 0
  lfm3:
    cmd: >-
      /usr/local/bin/llama-server
