      --alias lfm3
      --host 127.0.0.1 --port ${PORT}
      --ctx-size 4096 --predict 2654 --threads 4 --threads-batch 4
      --batch-size 256 --ubatch-size 128 --parallel 1 --n-gpu-layers 0
      --temp 0.1 --top-k 50 --top-p 1.0 --min-p 0.0 --repeat-penalty 1.1
    ttl: 300

groups:
  cpu:
    swap: true
    exclusive: true
    members: [joko, lfm3]

hooks:
  on_startup:
    preload: [joko]
# Optional Nginx proxy for text-only llama-swap
# Place in /etc/nginx/sites-available/inferance and symlink to sites-enabled/

limit_req_zone $binary_remote_addr zone=slm_limit:10m rate=5r/s;

server {
    listen 80 default_server;
    server_name _;

    client_max_body_size 1M;

    # ponytail: bufferless streaming configuration for Server-Sent Events (SSE)
    location / {
        # Rate limiting (allow burst of 10)
