use anyhow::{Context, Result};
use clap::{Parser, Subcommand};
use docdb::diff;
use docdb::generator;
use docdb::model::DatabaseSchema;
use docdb::parser;
use std::fs;
use std::path::{Path, PathBuf};

#[derive(Parser, Debug)]
#[command(
    name = "docdb",
    version = "0.1.0",
    about = "High-performance, local-first database documentation and interactive ERD generator in Rust"
)]
pub struct Cli {
    #[command(subcommand)]
    pub command: Commands,
}

#[derive(Subcommand, Debug)]
pub enum Commands {
    /// Build standalone documentation HTML or JSON
    Build {
        /// Input schema file path (.sql, .dbml)
        #[arg(value_name = "INPUT")]
        input: PathBuf,

        /// Output destination path
        #[arg(short, long, default_value = "./dist/index.html")]
        output: PathBuf,

        /// Output format: html (default) or json
        #[arg(short, long, default_value = "html")]
        format: String,

        /// Document title
        #[arg(long, default_value = "Database Documentation")]
        title: String,
    },

    /// Compare two schemas and generate a migration diff
    Diff {
        /// Base schema file (.sql or .dbml)
        #[arg(value_name = "BASE")]
        base: PathBuf,

        /// Target schema file (.sql or .dbml)
        #[arg(value_name = "TARGET")]
        target: PathBuf,

        /// Output format: terminal (default) or json
        #[arg(short, long, default_value = "terminal")]
        format: String,
    },

    /// Inspect and print a schema summary in the terminal
    Inspect {
        /// Input schema file path (.sql, .dbml)
        #[arg(value_name = "INPUT")]
        input: PathBuf,
    },
}

fn load_schema(path: &Path) -> Result<DatabaseSchema> {
    let content = fs::read_to_string(path)
        .with_context(|| format!("Failed to read file: {}", path.display()))?;

    let file_name = path
        .file_name()
        .and_then(|n| n.to_str())
        .unwrap_or("schema");

    let is_dbml = path
        .extension()
        .map(|ext| ext.eq_ignore_ascii_case("dbml"))
        .unwrap_or(false);

    if is_dbml {
        parser::parse_dbml(&content, file_name)
    } else {
        parser::parse_sql(&content, file_name)
    }
}

