import { cookies } from "next/headers";
import { redirect } from "next/navigation";
import { UsersManagementView } from "@/components/users/UsersManagementView";
import { ManagedUser } from "@/types/user";
import { ProfileData } from "@/types/dashboard";

export default async function UsersPage() {
  const cookieStore = await cookies();
  const token = cookieStore.get("token")?.value;

  if (!token) {
    redirect("/login");
  }

  const backendUrl = process.env.BACKEND_URL || "http://127.0.0.1:8000";

  let profile: ProfileData | null = null;
  let users: ManagedUser[] = [];

  try {
    const [profileRes, usersRes] = await Promise.all([
      fetch(`${backendUrl}/api/profile`, {
        headers: { Authorization: `Bearer ${token}` },
        cache: "no-store",
      }),
      fetch(`${backendUrl}/api/users`, {
        headers: { Authorization: `Bearer ${token}` },
        cache: "no-store",
      }),
    ]);

    if (profileRes.status === 401 || usersRes.status === 401) {
      redirect("/login");
    }

    if (!profileRes.ok || !usersRes.ok) {
      redirect("/login");
    }

    profile = await profileRes.json();
    users = await usersRes.json();
  } catch {
    redirect("/login");
  }

  if (profile?.must_set_birth_date) {
    redirect("/login");
  }

  if (!profile) {
    redirect("/login");
  }

  // Non-admin users cannot access the user management page
  if (profile.role !== "admin") {
    redirect("/");
  }

  return <UsersManagementView initialUsers={users} profile={profile} />;
}
