use axum::{
    extract::{Multipart, State},
    Json,
};
use crate::dto::upload::UploadResponse;
use crate::error::AppError;
use crate::middleware::AuthUser;
use crate::state::AppState;

const MAX_DOCUMENT_BYTES: usize = 10 * 1024 * 1024; // 10 MB

pub async fn upload_file(
    _auth: AuthUser,
    State(state): State<AppState>,
    mut multipart: Multipart,
) -> Result<Json<UploadResponse>, AppError> {
    let mut file_payload: Option<(String, String, Vec<u8>)> = None;

    while let Some(field) = multipart
        .next_field()
        .await
        .map_err(|e| AppError::BadRequest(format!("Failed to parse multipart: {:?}", e)))?
    {
        let field_name = field.name().unwrap_or("").to_string();
        if field_name == "file" || field_name == "document" || field_name == "upload" {
            let filename = field.file_name().unwrap_or("document.bin").to_string();
            let content_type = field.content_type().unwrap_or("application/octet-stream").to_string();

            let bytes = field
                .bytes()
                .await
                .map_err(|e| AppError::BadRequest(format!("Failed to read file bytes: {:?}", e)))?;

            if bytes.len() > MAX_DOCUMENT_BYTES {
                return Err(AppError::PayloadTooLarge(
                    "File exceeds 10MB size limit".to_string(),
                ));
            }

            file_payload = Some((filename, content_type, bytes.to_vec()));
            break;
        }
    }

    let Some((filename, content_type, bytes)) = file_payload else {
        return Err(AppError::BadRequest("No file provided in form-data field 'file'".to_string()));
    };

    let size = bytes.len();
    let url = state
        .storage
        .upload_file("documents", &filename, &bytes, &content_type)
        .await?;

    Ok(Json(UploadResponse {
        url,
        filename,
        content_type,
        size,
    }))
}
