"use client";
import type { ComponentPropsWithoutRef } from "react";
import type { Components, ExtraProps } from "react-markdown";
import ReactMarkdown from "react-markdown";
import remarkGfm from "remark-gfm";
import { Check, Copy } from "lucide-react";
import { useCopy } from "./MessageActions";

function CodeBlock({ lang, code }: { lang: string; code: string }) {
  const [copied, copy] = useCopy();
  return (
    <div className="my-4 overflow-hidden rounded-2xl bg-[#171717]">
      <div className="flex items-center justify-between bg-[#2a2a2a] px-4 py-2 text-xs text-muted">
        <span>{lang || "code"}</span>
        <button onClick={() => copy(code)} className="flex items-center gap-1.5 hover:text-text">
          {copied ? <Check size={14} /> : <Copy size={14} />} {copied ? "Disalin" : "Salin"}
        </button>
      </div>
      <pre className="overflow-x-auto p-4 text-sm leading-6">
        <code>{code}</code>
      </pre>
    </div>
  );
}

// Drop react-markdown's `node` prop so it doesn't reach the DOM.
function strip<T extends ExtraProps>(p: T): Omit<T, "node"> {
  const { node, ...rest } = p;
  void node;
  return rest;
}

type P<K extends keyof React.JSX.IntrinsicElements> = ComponentPropsWithoutRef<K> & ExtraProps;
const cell = "border-b border-[#2a2a2a] py-3 pr-4 last:pr-0 [&:not(:first-child)]:text-right";

const components: Components = {
  p: (p: P<"p">) => <p className="my-4 first:mt-0 last:mb-0" {...strip(p)} />,
  h1: (p: P<"h1">) => <h2 className="mb-2 mt-6 text-2xl font-semibold" {...strip(p)} />,
  h2: (p: P<"h2">) => <h2 className="mb-2 mt-6 text-xl font-semibold" {...strip(p)} />,
  h3: (p: P<"h3">) => <h3 className="mb-1 mt-5 text-lg font-semibold" {...strip(p)} />,
  ul: (p: P<"ul">) => <ul className="my-4 list-disc space-y-1 pl-6" {...strip(p)} />,
  ol: (p: P<"ol">) => <ol className="my-4 list-decimal space-y-1 pl-6" {...strip(p)} />,
  a: (p: P<"a">) => <a className="underline underline-offset-2" target="_blank" rel="noreferrer" {...strip(p)} />,
  blockquote: (p: P<"blockquote">) => <blockquote className="my-4 border-l-2 border-[#3a3a3a] pl-4 text-muted" {...strip(p)} />,
  hr: () => <hr className="my-6 border-[#2a2a2a]" />,
  strong: (p: P<"strong">) => <strong className="font-semibold" {...strip(p)} />,
  table: (p: P<"table">) => (
    <div className="my-4 overflow-x-auto">
      <table className="w-full border-collapse text-left" {...strip(p)} />
    </div>
  ),
  th: (p: P<"th">) => <th className={`${cell} font-semibold`} {...strip(p)} />,
  td: (p: P<"td">) => <td className={cell} {...strip(p)} />,
  pre: ({ children }) => <>{children}</>,
  code: ({ className, children }) => {
    const text = String(children ?? "");
    const lang = /language-(\w+)/.exec(className ?? "")?.[1];
    if (!lang && !text.includes("\n")) {
      return <code className="rounded-md bg-[#2a2a2a] px-1.5 py-0.5 text-[0.9em]">{children}</code>;
    }
    return <CodeBlock lang={lang ?? ""} code={text.replace(/\n$/, "")} />;
  },
};

export default function Markdown({ children }: { children: string }) {
  return (
    <div className="text-base leading-[1.75]">
      <ReactMarkdown remarkPlugins={[remarkGfm]} components={components}>
        {children}
      </ReactMarkdown>
    </div>
  );
}
